34	/** Most user prompts a session may have and still be eligible for replay. */
35	const MAX_PROMPTS = 2;
36	const TAG_LINE = /^\s*\[(roster setup=[^\]]*)\][ \t]*\r?\n?/;
37	const BRANCH_REFS = ["refs/heads/entire/checkpoints/v1", "refs/remotes/origin/entire/checkpoints/v1"];
