47	/** Splits a leading roster tag off a prompt. */
48	export function stripTag(prompt: string): { tag: string | null; prompt: string } {
49	  const m = TAG_LINE.exec(prompt);
50	  return m ? { tag: m[1]!, prompt: prompt.slice(m[0].length).trim() } : { tag: null, prompt: prompt.trim() };
51	}
