61	/** Assistant turns in a Claude Code transcript: distinct assistant messages (one message can span several rows). */
62	export function countAssistantTurns(text: string | null): number | null {
63	  if (!text) return null;
64	  const ids = new Set<string>();
65	  let anon = 0;
66	  for (const line of text.split("\n")) {
67	    if (!line.trim()) continue;
68	    let r: any;
69	    try {
70	      r = JSON.parse(line);
71	    } catch {
72	      continue;
73	    }
74	    if (r?.type !== "assistant" || !r.message) continue;
75	    if (typeof r.message.id === "string" && r.message.id) ids.add(r.message.id);
76	    else anon++;
77	  }
78	  const n = ids.size + anon;
79	  return n > 0 ? n : null;
80	}
