82	/** Session id → commits whose checkpoint trailer names a checkpoint holding that session. */
83	function linkIndex(repo: string): Map<string, Link[]> {
84	  const index = new Map<string, Link[]>();
85	  const log = tryGit(repo, [
86	    "log",
87	    "--all",
88	    "--format=%H%x1f%ct%x1f%(trailers:key=Entire-Checkpoint,valueonly,separator=%x2c)%x1e",
89	  ]);
90	  const ref = BRANCH_REFS.find((r) => tryGit(repo, ["rev-parse", "--verify", "-q", r]) !== null);
91	  if (!log || !ref) return index;
92	  const show = (path: string): any => {
93	    const out = tryGit(repo, ["show", `${ref}:${path}`]);
94	    try {
95	      return out === null ? null : JSON.parse(out);
96	    } catch {
97	      return null;
98	    }
99	  };
100	  for (const rec of log.split("\x1e")) {
101	    const [sha, ct, ids] = rec.trim().split("\x1f");
102	    if (!sha || !ids) continue;
103	    for (const id of ids.split(",").map((s) => s.trim()).filter(Boolean)) {
104	      const dir = `${id.slice(0, 2)}/${id.slice(2)}`;
105	      const root = show(`${dir}/metadata.json`);
106	      if (!root) continue;
107	      const n = Array.isArray(root.sessions) ? root.sessions.length : 0;
108	      for (let i = 0; i < n; i++) {
109	        const sid = show(`${dir}/${i}/metadata.json`)?.session_id;
110	        if (typeof sid !== "string") continue;
111	        (index.get(sid) ?? index.set(sid, []).get(sid)!).push({
112	          sha,
113	          time: Number(ct),
114	          importStrategy: root.strategy === "import",
115	          turns: () => countAssistantTurns(tryGit(repo, ["show", `${ref}:${dir}/${i}/full.jsonl`])),
116	        });
117	      }
118	    }
119	  }
120	  return index;
121	}
