123	/** Tasks plus the sessions that could not become one, each with its reason. */
124	export function planReplayTasks(
125	  repo: string,
126	  sessions: Session[],
127	  outcomes: Outcome[],
128	): { tasks: ReplayTask[]; skipped: SkippedSession[] } {
129	  const tercile = new Map(outcomes.map((o) => [o.session_id, o.tercile]));
130	  const links = linkIndex(repo);
131	  const tasks: (ReplayTask & { time: number })[] = [];
132	  const skipped: SkippedSession[] = [];
133	  const seen = new Set<string>();
134	
135	  for (const s of sessions) {
136	    if (seen.has(s.id)) continue;
137	    seen.add(s.id);
138	    const mine = sessions.filter((x) => x.id === s.id);
139	    const found = new Map<string, Link>((links.get(s.id) ?? []).map((l) => [l.sha, l]));
140	    for (const x of mine) {
141	      if (x.commit_sha && !found.has(x.commit_sha)) {
142	        const t = tryGit(repo, ["show", "-s", "--format=%ct", x.commit_sha]);
143	        if (t !== null) found.set(x.commit_sha, { sha: x.commit_sha, time: Number(t), importStrategy: false, turns: () => null });
144	      }
145	    }
146	    const commits = [...found.values()].sort((a, b) => a.time - b.time || a.sha.localeCompare(b.sha));
147	    if (commits.length === 0) {
148	      skipped.push({ sessionId: s.id, reason: "no linked commit" });
149	      continue;
150	    }
151	    const earliest = commits[0]!;
152	    const latest = commits.at(-1)!;
153	    const parentSha = tryGit(repo, ["rev-parse", `${earliest.sha}^1`]);
154	    if (!parentSha) {
155	      skipped.push({ sessionId: s.id, reason: `earliest commit ${earliest.sha.slice(0, 7)} has no parent` });
156	      continue;
157	    }
158	
159	    const userPrompts = Math.max(...mine.map((x) => x.n_user_prompts));
160	    const tests = hiddenTestsForCommits(repo, commits.map((c) => c.sha));
161	    let track: ReplayTask["track"];
162	    let reason: string;
163	    if (commits.some((c) => c.importStrategy)) [track, reason] = ["none", "imported history, not captured live"];
164	    else if (userPrompts > MAX_PROMPTS) [track, reason] = ["none", `${userPrompts} user prompts (more than ${MAX_PROMPTS})`];
165	    else if (tests.length === 0) [track, reason] = ["judge-only", "no hidden tests in the original change"];
166	    else [track, reason] = ["tests", `${tests.length} hidden test file(s)`];
167	
168	    const turnCounts = (links.get(s.id) ?? []).map((l) => l.turns()).filter((n): n is number => n !== null);
169	    const originalTurns = turnCounts.length ? Math.max(...turnCounts) : null;
170	
171	    const { tag, prompt } = stripTag(s.first_prompt);
172	    tasks.push({
173	      id: s.id,
174	      sessionId: s.id,
175	      setupId: s.setup_id,
176	      tag,
177	      prompt,
178	      parentSha,
179	      originalSha: latest.sha,
180	      hiddenTests: tests,
181	      userPrompts,
182	      originalTurns,
183	      tercile: tercile.get(s.id) ?? null,
184	      track,
185	      reason,
186	      time: latest.time,
187	    });
188	  }
189	  tasks.sort((a, b) => a.time - b.time || a.originalSha.localeCompare(b.originalSha) || a.id.localeCompare(b.id));
190	  return { tasks: tasks.map(({ time: _t, ...t }) => t), skipped };
191	}
192	
193	export function buildReplayTasks(repo: string, sessions: Session[], outcomes: Outcome[]): ReplayTask[] {
194	  return planReplayTasks(repo, sessions, outcomes).tasks;
195	}
